@Test func ashWednesdayShowsTheRealPrecesFerialesText() async throws {
    guard let bundle = RealCorpus.bundle else { return }
    let corpus = bundle.makeLatinCorpus()
    let context = ConditionalContext(rubrica: "Rubrics 1960 - 1960", tempore: "Quadragesima", feria: 4, ad: "vesperas", mense: 2)
    let assembler = HourAssembler(corpus: corpus, context: context, calendar: SanctoralCalendar(entries: bundle.calendar))
    let hour = try #require(assembler.assembleVespers(day: 18, month: 2, year: 2026, priest: false))

    let precesFeriales = try #require(hour.sections.first { $0.kind == .precesFeriales })
    let fixtureText = try #require(try await OracleFixture.shared.main(year: 2026, date: "2026-02-18"))
    let diff = mismatches(hour: Hour(sections: [precesFeriales]), fixtureText: fixtureText, sectionKinds: [.precesFeriales])
    #expect(diff.isEmpty, "\(diff.count) unit(s) not found in the oracle fixture:\n\(diff.joined(separator: "\n"))")

    // The Pope/Bishop name placeholder is confirmed left literal by DO's own real
    // output (no dynamic "reigning Pope" data source exists even there) -- not a gap.
    #expect(precesFeriales.units.contains { if case .versicleResponse(let v, _, _, _) = $0 { return v.contains("Papa nostro N.") } else { return false } })
}

@Test func sundayWithinTheChristmasOctaveUsesNat1_0sOwnAntiphonsFor28December2025() async throws {
    // 2025-12-28 is the one day that year the Sunday within the Christmas Octave
    // falls on (Occurrence.temporalPath's own "26-31 December" redirect, added
    // 2026-09-17 after finding real DO output never reaches the plain day-numbered
    // "Nat28" file here at all). Holy Innocents (Sancti/12-28, rank 5.4) and the
    // Sunday (via Nat1-0, also 5.4) are exactly tied under 1960 rubrics, so this also
    // exercises that the Sunday's *real* rank -- not some other file's -- is what the
    // occurrence comparison actually sees.
    guard let bundle = RealCorpus.bundle else { return }
    let corpus = bundle.makeLatinCorpus()
    let context = ConditionalContext(rubrica: "Rubrics 1960 - 1960", tempore: "Nativitas", feria: 1, ad: "vesperas", mense: 12)
    let assembler = HourAssembler(corpus: corpus, context: context, calendar: SanctoralCalendar(entries: bundle.calendar))
    let hour = try #require(assembler.assembleVespers(day: 28, month: 12, year: 2025, priest: false))

    let fixtureText = try #require(try await OracleFixture.shared.main(year: 2025, date: "2025-12-28"))
    // .psalmodia excluded from the full diff: Psalm 111 (one of this day's five) hits
    // the same already-documented Bea/Vulgate half-verse-numbering gap the 19
    // January/Agatha tests already exclude it for -- not a new issue this date
    // introduces. The antiphon-selection assertion below is independent of that gap.
    let diff = mismatches(hour: hour, fixtureText: fixtureText, sectionKinds: [.introductio, .conclusio])
    #expect(diff.isEmpty, "\(diff.count) unit(s) not found in the oracle fixture:\n\(diff.joined(separator: "\n"))")

    let psalmodia = try #require(hour.sections.first { $0.kind == .psalmodia })
    #expect(psalmodia.units.contains(.antiphon("Tecum princípium * in die virtútis tuæ, in splendóribus sanctórum, ex útero ante lucíferum génui te.")))
}

@Test func plainPaschaltideWeekdayReplacesPsalmAntiphonsWithAllelúia() async throws {
    // 20 April 2026: a plain ferial Monday within Paschaltide (week "Pasc2", IV.
    // classis, no Sancti office) -- confirmed real fixture shows every psalm antiphon
    // as alleluia_ant()'s "Allelúia, * allelúia, allelúia." rather than the plain
    // ferial schedule's own text.
    guard let bundle = RealCorpus.bundle else { return }
    let corpus = bundle.makeLatinCorpus()
    let context = ConditionalContext(rubrica: "Rubrics 1960 - 1960", tempore: "post Pascha", feria: 2, ad: "vesperas", mense: 4)
    let assembler = HourAssembler(corpus: corpus, context: context, calendar: SanctoralCalendar(entries: bundle.calendar))
    let hour = try #require(assembler.assembleVespers(day: 20, month: 4, year: 2026, priest: false))

    let fixtureText = try #require(try await OracleFixture.shared.main(year: 2026, date: "2026-04-20"))
    let diff = mismatches(hour: hour, fixtureText: fixtureText, sectionKinds: [.introductio, .conclusio])
    #expect(diff.isEmpty, "\(diff.count) unit(s) not found in the oracle fixture:\n\(diff.joined(separator: "\n"))")

    let psalmodia = try #require(hour.sections.first { $0.kind == .psalmodia })
    let alleluiaCount = psalmodia.units.filter { $0 == .antiphon("Allelúia, * allelúia, allelúia.") }.count
    #expect(alleluiaCount == 10, "expected all 5 psalms bracketed by the Allelúia antiphon (open+close each), found \(alleluiaCount)")
}

@Test func englishSectionsMatchTheRealBilingualFixtureFor16September2026() async throws {
    // CLAUDE.md's own visual-spec worked example, checked here against the bilingual
    // spot-check fixture (Latin and English are two separate blocks per section in
    // DO's own rendering, not interleaved verse-by-verse -- confirmed by inspecting the
    // raw fixture directly). English is compared against the *unnormalised* fixture
    // text: LatinOrthography.normalize (J-to-I) must never touch English (CLAUDE.md:
    // "Never touch English"), so running it over this bilingual fixture as a whole
    // would risk corrupting real English words containing "j" (e.g. "rejoice").
    guard let bundle = RealCorpus.bundle else { return }
    let corpus = bundle.makeLatinCorpus()
    let context = ConditionalContext(rubrica: "Rubrics 1960 - 1960", tempore: "post Pentecosten", feria: 4, ad: "vesperas", mense: 9)
    let assembler = HourAssembler(corpus: corpus, context: context, calendar: SanctoralCalendar(entries: bundle.calendar), englishCorpus: bundle.makeEnglishCorpus())
    let hour = try #require(assembler.assembleVespers(day: 16, month: 9, year: 2026, priest: false))

    let fixtureText = try #require(try await OracleFixture.shared.spotCheck(filename: "2026-09-16_priestN_bilingual_visual-spec-example.txt"))
    let normalizedFixture = collapsedWhitespace(fixtureText.replacingOccurrences(of: "✠", with: "+"))

    func englishTexts(_ unit: BreviariumKit.Unit) -> [String] {
        switch unit {
        case .rubric(_, let english): return [english].compactMap { $0 }
        case .versicleResponse(_, _, let v, let r): return [v, r].compactMap { $0 }
        case .verse(_, _, _, let first, let second):
            guard let first, let second else { return [] }
            guard !second.isEmpty else { return [first] }
            let withoutAsterisk = first.hasSuffix("*") ? String(first.dropLast()) : first
            return ["\(withoutAsterisk) * \(second)"]
        case .antiphon(_, let english): return [english].compactMap { $0 }
        case .prose(_, let english): return [english].compactMap { $0 }
        }
    }

    var missing: [String] = []
    for section in hour.sections
    where [.introductio, .psalmodia, .canticum, .oratio, .capitulum, .hymnus, .versus, .conclusio].contains(section.kind) {
        for unit in section.units {
            for piece in englishTexts(unit) {
                let text = collapsedWhitespace(piece)
                guard !text.isEmpty else { continue }
                if !normalizedFixture.contains(text) { missing.append("[\(section.kind)] \(text)") }
            }
        }
    }
    #expect(missing.isEmpty, "\(missing.count) English unit(s) not found in the bilingual fixture:\n\(missing.joined(separator: "\n"))")

    // At least one real English unit was actually produced and checked per wired
    // section, not just an empty (vacuously passing) diff.
    let introductio = try #require(hour.sections.first { $0.kind == .introductio })
    #expect(introductio.units.contains(.versicleResponse(
        versicle: "Deus + in adiutórium meum inténde.", response: "Dómine, ad adiuvándum me festína.",
        versicleEnglish: "O God, + come to my assistance;", responseEnglish: "O Lord, make haste to help me."
    )))

    let canticum = try #require(hour.sections.first { $0.kind == .canticum })
    #expect(canticum.units.contains(.antiphon(
        "Gaudent in cælis * ánimæ Sanctórum, qui Christi vestígia sunt secúti: et quia pro eius amóre sánguinem suum fudérunt, ídeo cum Christo exsúltant sine fine.",
        english: "In heaven do rejoice the souls of the Saints * who have followed the steps of Christ; and because they shed their blood for the love of Christ, therefore shall they be made glad for ever with Christ."
    )))
    // The Magnificat itself (Luke 1:46-55, New Testament) has no Bea/Vulgate numbering
    // divergence to worry about -- its own verses pair cleanly. This specifically
    // covers a real bug found via this exact assertion: Psalm232.txt's own leading
    // "(Canticum B. Mariæ Virginis * Luc. 1:46-55)" title-comment line was being
    // misparsed by ConditionalLineProcessor as a false (sed ...)-style condition,
    // silently swallowing verse "1:46" itself -- fixed by SectionResolver.resolvePsalmText
    // reading psalm/canticle text raw, bypassing conditional-line processing entirely,
    // matching DO's own real behaviour (horasscripts.pl's plain do_read for these files).
    #expect(canticum.units.contains {
        if case .verse(let ref, _, _, let firstEnglish, _) = $0 { return ref == "1:46" && firstEnglish != nil } else { return false }
    })
    // Psalm 127 (this office's own weekday psalm) does NOT pair, and this is a real,
    // confirmed data-quality issue in the pinned DO checkout, not our bug: the Bea
    // Latin-Bea/Psalterium/Psalmorum/Psalm127.txt mislabels its own 4th verse as
    // "127:3" (a bare repeat of the number, immediately after "127:3a"/"127:3b") instead
    // of "127:4", breaking the exact reference-sequence match against English's clean
    // "127:1,2,3a,3b,4,5,6". Confirming this falls back to Latin-only (not a silently
    // wrong pairing) is the point of this assertion.
    let psalmodia = try #require(hour.sections.first { $0.kind == .psalmodia })
    let psalm127Verses = psalmodia.units.filter { if case .verse(let ref, _, _, _, _) = $0 { return ref.hasPrefix("127:") } else { return false } }
    #expect(!psalm127Verses.isEmpty)
    #expect(psalm127Verses.allSatisfy { if case .verse(_, _, _, let firstEnglish, _) = $0 { return firstEnglish == nil } else { return false } })
    // The Gloria doxology that follows Psalm 127 is fixed, 2-line, and always pairs
    // positionally regardless of any psalm-specific numbering divergence.
    #expect(psalmodia.units.contains {
        if case .verse(let ref, _, _, let firstEnglish, _) = $0 { return ref.isEmpty && firstEnglish != nil } else { return false }
    })

    // The versicle itself is a real, confirmed DO English-tree gap, not our bug:
    // Commune/C3.txt's English side has no [Versum 3] at all (only [Versum 1]/[Versum
    // 2] directly) even though its Latin side does (as `@:Versum 2`, confirmed a
    // universal alias pattern across Commune/C1.txt/C1p.txt/C2.txt/C4.txt/C5.txt, but
    // *not* universal on real office files -- several alias to Versum 1 instead, and
    // some carry a genuinely distinct versicle -- so this can't be simplified to always
    // querying "Versum 2" directly). Correctly resolving `resolvedLocation`'s "same
    // exact section" rule here means English stays nil rather than guessing.
    let versus = try #require(hour.sections.first { $0.kind == .versus })
    #expect(versus.units.contains(.versicleResponse(versicle: "Exsultábunt Sancti in glória.", response: "Lætabúntur in cubílibus suis.")))
}

@Test func easterSundayIntroductioAndConclusioMatchTheRealOracleWithPriestForm() async throws {
    guard let bundle = RealCorpus.bundle else { return }
    let corpus = bundle.makeLatinCorpus()
    let context = ConditionalContext(rubrica: "Rubrics 1960 - 1960", tempore: "post Pascha", feria: 1, ad: "vesperas", mense: 4)
    let assembler = HourAssembler(corpus: corpus, context: context, calendar: SanctoralCalendar(entries: bundle.calendar))
    let hour = try #require(assembler.assembleVespers(day: 5, month: 4, year: 2026, priest: true))

    let fixtureText = try #require(try await OracleFixture.shared.spotCheck(filename: "2026-04-05_priestY_latin_easter.txt"))
    let diff = mismatches(hour: hour, fixtureText: fixtureText, sectionKinds: [.introductio, .conclusio])
    #expect(diff.isEmpty, "\(diff.count) unit(s) not found in the oracle fixture:\n\(diff.joined(separator: "\n"))")
}
